# Surah Al-Hadid (chapter 57) — part 2: ayat 17-29 (IDs 5092-5104)
SURAH = 57

ENTRIES = {
5092: (
"جان لو کہ اللہ زمین کو اس کی موت کے بعد زندہ کرتا ہے — ہم نے تمہارے لیے آیات کھول دی ہیں تاکہ تم سمجھو",
"""۱۔ زمین کی زندگی — اعلموا أن الله یحیي الأرض بعد موتها؛ قد بینا لکم الآیات لعلکم تعقلون۔
۲۔ ’’اعْلَمُوا أَنَّ اللَّهَ يُحْيِي الْأَرْضَ بَعْدَ مَوْتِهَا قَدْ بَيَّنَّا لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَعْقِلُونَ‘‘ — جان لو کہ اللہ زمین کو اس کی موت کے بعد زندہ کرتا ہے — ہم نے تمہارے لیے آیات کھول دی ہیں تاکہ تم سمجھو — یعنی جان لو کہ اللہ زمین کو اس کی موت کے بعد زندہ کرتا ہے ہم نے تمہارے لیے آیات کھول دی ہیں تاکہ تم سمجھو۔
۳۔ عملی سبق: اللہ کی قدرت پر یقین رکھو؛ اللہ سے ڈرو۔"""
),
5093: (
"بے شک صدقہ دینے والے مرد اور عورتیں اور جنہوں نے اللہ کو قرض حسن دیا دوگنا کیا جائے گا اور ان کے لیے کریم اجر ہے",
"""۱۔ قرضِ حسن — إن المصدّقین و المصدّقات و أقرضوا الله قرضًا حسنًا یُضاعف لهم و لهم أجر کریم۔
۲۔ ’’إِنَّ الْمُصَّدِّقِينَ وَالْمُصَّدِّقَاتِ وَأَقْرَضُوا اللَّهَ قَرْضًا حَسَنًا يُضَاعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ‘‘ —بے شک صدقہ دینے والے مرد اور عورتیں اور جنہوں نے اللہ کو قرض حسن دیا دوگنا کیا جائے گا اور ان کے لیے کریم اجر ہے۔
۳۔ عملی سبق: صدقہ دو؛ اللہ سے ڈرو۔"""
),
5094: (
"اور جو اللہ اور اس کے رسولوں پر ایمان لائے وہی صدیقین ہیں — اور شہداء اپنے رب کے پاس ہیں ان کا اجر اور ان کا نور ہے — اور جنہوں نے کفر کیا اور ہماری آیات جھٹلائیں وہی جہنم والے ہیں",
"""۱۔ صدیقین و شہداء — و الذین آمنوا بالله و رسله أولئک هم الصدّیقون؛ و الشهداء عند ربهم لهم أجرهم و نورهم؛ و الذین کفروا و کذّبوا بآیاتنا أولئک أصحاب الجحیم۔
۲۔ ’’وَالَّذِينَ آمَنُوا بِاللَّهِ وَرُسُلِهِ أُولَٰئِكَ هُمُ الصِّدِّيقُونَ وَالشُّهَدَاءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا أُولَٰئِكَ أَصْحَابُ الْجَحِيمِ‘‘ — اور جو اللہ اور اس کے رسولوں پر ایمان لائے وہی صدیقین ہیں — اور شہداء اپنے رب کے پاس ہیں ان کا اجر اور ان کا نور ہے — اور جنہوں نے کفر کیا اور ہماری آیات جھٹلائیں وہی جہنم والے ہیں — یعنی اور جو اللہ اور اس کے رسولوں پر ایمان لائے وہی صدیقین ہیں اور شہداء اپنے رب کے پاس ہیں ان کا اجر اور ان کا نور ہے اور جنہوں نے کفر کیا اور ہماری آیات جھٹلائیں وہی جہنم والے ہیں۔
۳۔ عملی سبق: ایمان لاؤ؛ اللہ سے ڈرو۔"""
),
5095: (
"جان لو کہ دنیا کی زندگی تو کھیل تماشہ اور زینت اور تمہارے درمیان فخر اور مال و اولاد کی کثرت ہے — جیسے بارش جس کی نباتات کو دیکھ کر کافر خوش ہوتے ہیں پھر وہ خشک ہو جاتی ہے پھر تم اسے پیلا دیکھتے ہو پھر وہ بھوسہ ہو جاتی ہے — اور آخرت میں سخت عذاب ہے اور اللہ کی طرف سے بخشش اور رضامندی — اور دنیا کی زندگی تو دھوکے کا سامان ہے",
"""۱۔ دنیا کی حقیقت — اعلموا أنما الحیاة الدنیا لعب و لهو و زینة و تفاخر بینکم و تکاثر في الأموال و الأولاد؛ کمثل غیث أعجب الکفار نباته ثم یهیج فتراه مصفرًا ثم یکون حطامًا؛ و في الآخرة عذاب شدید و مغفرة من الله و رضوان؛ و ما الحیاة الدنیا إلا متاع الغرور۔
۲۔ ’’اعْلَمُوا أَنَّمَا الْحَيَاةُ الدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَۃٌ وَتَفَاخُرٌ بَيْنَكُمْ وَتَكَاثُرٌ فِي الْأَمْوَالِ وَالْأَوْلَادِ كَمَثَلِ غَيْثٍ أَعْجَبَ الْكُفَّارَ نَبَاتُهُ ثُمَّ يَهِيجُ فَتَرَاهُ مُصْفَرًّا ثُمَّ يَكُونُ حُطَامًا وَفِي الْآخِرَۃِ عَذَابٌ شَدِيدٌ وَمَغْفِرَۃٌ مِّنَ اللَّهِ وَرِضْوَانٌ وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا مَتَاعُ الْغُرُورِ‘‘ — جان لو کہ دنیا کی زندگی تو کھیل تماشہ اور زینت اور تمہارے درمیان فخر اور مال و اولاد کی کثرت ہے — جیسے بارش جس کی نباتات کو دیکھ کر کافر خوش ہوتے ہیں پھر وہ خشک ہو جاتی ہے پھر تم اسے پیلا دیکھتے ہو پھر وہ بھوسہ ہو جاتی ہے — اور آخرت میں سخت عذاب ہے اور اللہ کی طرف سے بخشش اور رضامندی — اور دنیا کی زندگی تو دھوکے کا سامان ہے — یعنی جان لو کہ دنیا کی زندگی تو کھیل تماشہ اور زینت اور تمہارے درمیان فخر اور مال و اولاد کی کثرت ہے جیسے بارش جس کی نباتات کو دیکھ کر کافر خوش ہوتے ہیں پھر وہ خشک ہو جاتی ہے پھر تم اسے پیلا دیکھتے ہو پھر وہ بھوسہ ہو جاتی ہے اور آخرت میں سخت عذاب ہے اور اللہ کی طرف سے بخشش اور رضامندی اور دنیا کی زندگی تو دھوکے کا سامان ہے۔
۳۔ عملی سبق: دنیا کی زینت پر مغرور نہ ہو؛ اللہ سے ڈرو۔"""
),
5096: (
"سبقت کرو اپنے رب کی بخشش کی طرف اور ایسی جنت کی طرف جس کی چوڑائی آسمان و زمین کی چوڑائی جیسی ہے جو تیار کی گئی ان کے لیے جو اللہ اور اس کے رسولوں پر ایمان لائے — یہ اللہ کا فضل ہے وہ جسے چاہے دیتا ہے — اور اللہ بہت بڑے فضل والا ہے",
"""۱۔ سبقت کرو — سابقوا إلی مغفرۃ من ربکم و جنة عرضها کعرض السماء و الأرض أعدّت للذین آمنوا بالله و رسله؛ ذلک فضل الله یؤتیه من یشاء؛ و الله ذو الفضل العظیم۔
۲۔ ’’سَابِقُوا إِلَىٰ مَغْفِرَۃٍ مِّن رَّبِّكُمْ وَجَنَّۃٍ عَرْضُهَا كَعَرْضِ السَّمَاءِ وَالْأَرْضِ أُعِدَّتْ لِلَّذِينَ آمَنُوا بِاللَّهِ وَرُسُلِهِ ذَٰلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ‘‘ — سبقت کرو اپنے رب کی بخشش کی طرف اور ایسی جنت کی طرف جس کی چوڑائی آسمان و زمین کی چوڑائی جیسی ہے جو تیار کی گئی ان کے لیے جو اللہ اور اس کے رسولوں پر ایمان لائے — یہ اللہ کا فضل ہے وہ جسے چاہے دیتا ہے — اور اللہ بہت بڑے فضل والا ہے — یعنی سبقت کرو اپنے رب کی بخشش کی طرف اور ایسی جنت کی طرف جس کی چوڑائی آسمان و زمین کی چوڑائی جیسی ہے جو تیار کی گئی ان کے لیے جو اللہ اور اس کے رسولوں پر ایمان لائے یہ اللہ کا فضل ہے وہ جسے چاہے دیتا ہے اور اللہ بہت بڑے فضل والا ہے۔
۳۔ عملی سبق: اللہ کی بخشش کی طرف دوڑو؛ اللہ سے ڈرو۔"""
),
5097: (
"کوئی مصیبت زمین میں اور نہ تمہارے نفسوں میں پہنچتی ہے مگر وہ ایک کتاب میں ہے اس سے پہلے کہ ہم اسے پیدا کریں — بے شک یہ اللہ پر آسان ہے",
"""۱۔ کتابِ تقدیر — ما أصاب من مصيبۃ في الأرض و لا في أنفسکم إلا في کتاب من قبل أن نبرأها؛ إن ذلک علی الله یسیر۔
۲۔ ’’مَا أَصَابَ مِن مُّصِيبَۃٍ فِي الْأَرْضِ وَلَا فِي أَنفُسِكُمْ إِلَّا فِي كِتَابٍ مِّن قَبْلِ أَن نَّبْرَأَهَا إِنَّ ذَٰلِكَ عَلَى اللَّهِ يَسِيرٌ‘‘ — کوئی مصیبت زمین میں اور نہ تمہارے نفسوں میں پہنچتی ہے مگر وہ ایک کتاب میں ہے اس سے پہلے کہ ہم اسے پیدا کریں — بے شک یہ اللہ پر آسان ہے — یعنی کوئی مصیبت زمین میں اور نہ تمہارے نفسوں میں پہنچتی ہے مگر وہ ایک کتاب میں ہے اس سے پہلے کہ ہم اسے پیدا کریں بے شک یہ اللہ پر آسان ہے۔
۳۔ عملی سبق: تقدیر پر بھروسہ رکھو؛ اللہ سے ڈرو۔"""
),
5098: (
"تاکہ تم اس پر افسوس نہ کرو جو تم سے فوت ہو گیا اور اس پر نہ اتراؤ جو اس نے تمہیں دیا — اور اللہ کسی متکبر فخری کو پسند نہیں کرتا",
"""۱۔ نہ افسوس نہ اتراؤ — لکیلا تأسوا علی ما فاتکم و لا تفرحوا بما آتاکم؛ و الله لا یحب کل مختال فخور۔
۲۔ ’’لِّكَيْلَا تَأْسَوْا عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا بِمَا آتَاكُمْ وَاللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ‘‘ — تاکہ تم اس پر افسوس نہ کرو جو تم سے فوت ہو گیا اور اس پر نہ اتراؤ جو اس نے تمہیں دیا — اور اللہ کسی متکبر فخری کو پسند نہیں کرتا — یعنی تاکہ تم اس پر افسوس نہ کرو جو تم سے فوت ہو گیا اور اس پر نہ اتراؤ جو اس نے تمہیں دیا اور اللہ کسی متکبر فخری کو پسند نہیں کرتا۔
۳۔ عملی سبق: تکبر اور فخر سے بچو؛ اللہ سے ڈرو۔"""
),
5099: (
"جو بخل کرتے ہیں اور لوگوں کو بخل کا حکم دیتے ہیں — اور جو منہ موڑے تو بے شک اللہ غنی حمید ہے",
"""۱۔ بخل — الذین یبخلون و یأمرون الناس بالبخل؛ و من یتولّ فإن الله هو الغني الحمید۔
۲۔ ’’الَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِ وَمَن يَتَوَلَّ فَإِنَّ اللَّهَ هُوَ الْغَنِيُّ الْحَمِيدُ‘‘ — جو بخل کرتے ہیں اور لوگوں کو بخل کا حکم دیتے ہیں — اور جو منہ موڑے تو بے شک اللہ غنی حمید ہے — یعنی جو بخل کرتے ہیں اور لوگوں کو بخل کا حکم دیتے ہیں اور جو منہ موڑے تو بے شک اللہ غنی حمید ہے۔
۳۔ عملی سبق: بخل سے بچو؛ اللہ سے ڈرو۔"""
),
5100: (
"ہم نے اپنے رسولوں کو کھلی آیات کے ساتھ بھیجا اور ان کے ساتھ کتاب اور میزان اتاری تاکہ لوگ انصاف پر قائم رہیں — اور ہم نے لوہا اتارا جس میں سخت طاقت ہے اور لوگوں کے لیے فائدے ہیں — اور تاکہ اللہ جان لے کہ کون اسے اور اس کے رسولوں کی مدد غیب میں کرتا ہے — بے شک اللہ قوی عزیز ہے",
"""۱۔ کتاب و میزان اور لوہا — لقد أرسلنا رسلنا بالبینات و أنزلنا معهم الکتاب و المیزان لیقوم الناس بالقسط؛ و أنزلنا الحدید فیه بأس شدید و منافع للناس و لیعلم الله من ینصره و رسله بالغیب؛ إن الله قوي عزیز۔
۲۔ ’’لَقَدْ أَرْسَلْنَا رُسُلَنَا بِالْبَيِّنَاتِ وَأَنزَلْنَا مَعَهُمُ الْكِتَابَ وَالْمِيزَانَ لِيَقُومَ النَّاسُ بِالْقِسْطِ وَأَنزَلْنَا الْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَافِعُ لِلنَّاسِ وَلِيَعْلَمَ اللَّهُ مَن يَنصُرُهُ وَرُسُلَهُ بِالْغَيْبِ إِنَّ اللَّهَ قَوِيٌّ عَزِيزٌ‘‘ — ہم نے اپنے رسولوں کو کھلی آیات کے ساتھ بھیجا اور ان کے ساتھ کتاب اور میزان اتاری تاکہ لوگ انصاف پر قائم رہیں — اور ہم نے لوہا اتارا جس میں سخت طاقت ہے اور لوگوں کے لیے فائدے ہیں — اور تاکہ اللہ جان لے کہ کون اسے اور اس کے رسولوں کی مدد غیب میں کرتا ہے — بے شک اللہ قوی عزیز ہے — یعنی ہم نے اپنے رسولوں کو کھلی آیات کے ساتھ بھیجا اور ان کے ساتھ کتاب اور میزان اتاری تاکہ لوگ انصاف پر قائم رہیں اور ہم نے لوہا اتارا جس میں سخت طاقت ہے اور لوگوں کے لیے فائدے ہیں اور تاکہ اللہ جان لے کہ کون اسے اور اس کے رسولوں کی مدد غیب میں کرتا ہے بے شک اللہ قوی عزیز ہے۔
۳۔ عملی سبق: انصاف قائم کرو؛ اللہ سے ڈرو۔"""
),
5101: (
"اور ہم نے نوح اور ابراہیم کو بھیجا اور ان کی نسل میں نبوت اور کتاب رکھی — پس ان میں سے ہدایت پانے والا ہے اور ان میں سے اکثر فاسق ہیں",
"""۱۔ نبوت و کتاب — و لقد أرسلنا نوحًا و إبراهیم و جعلنا في ذریتهما النبوۃ و الکتاب؛ فمنهم مهتدٍ و کثیر منهم فاسقون۔
۲۔ ’’وَلَقَدْ أَرْسَلْنَا نُوحًا وَإِبْرَاهِيمَ وَجَعَلْنَا فِي ذُرِّيَّتِهِمَا النُّبُوَّۃَ وَالْكِتَابَ فَمِنْهُم مُّهْتَدٍ وَكَثِيرٌ مِّنْهُمْ فَاسِقُونَ‘‘ — اور ہم نے نوح اور ابراہیم کو بھیجا اور ان کی نسل میں نبوت اور کتاب رکھی — پس ان میں سے ہدایت پانے والا ہے اور ان میں سے اکثر فاسق ہیں — یعنی اور ہم نے نوح اور ابراہیم کو بھیجا اور ان کی نسل میں نبوت اور کتاب رکھی پس ان میں سے ہدایت پانے والا ہے اور ان میں سے اکثر فاسق ہیں۔
۳۔ عملی سبق: رسولوں کی تصدیق کرو؛ اللہ سے ڈرو۔"""
),
5102: (
"پھر ہم نے ان کے پیچھے اپنے رسول بھیجے اور مریم کے بیٹے عیسیٰ کو بھیجا اور اسے انجیل دی اور جنہوں نے اس کی پیروی کی ان کے دلوں میں نرمی اور رحم رکھا — اور راہبانہ جسے انہوں نے از خود ایجاد کیا ہم نے ان پر نہیں لکھا تھا سوائے اللہ کی خوشنودی حاصل کرنے کے — پس انہوں نے اس کی حق روایت نہیں کی — پس جنہوں نے ان میں سے ایمان لایا ہم نے انہیں ان کا اجر دیا — اور ان میں سے اکثر فاسق ہیں",
"""۱۔ عیسیٰ اور راہبانہ — ثم قفینا علی آثارهم برسلنا و قفینا بعیسی ابن مریم و آتیناه الإنجیل و جعلنا في قلوب الذین اتبعوه رأفۃ و رحمة؛ و رهبانیۃ ابتدعوها ما کتبناها علیهم إلا ابتغاء رضوان الله فما رعوها حق رعایته؛ فآتینا الذین آمنوا منهم أجرهم؛ و کثیر منهم فاسقون۔
۲۔ ’’ثُمَّ قَفَّيْنَا عَلَىٰ آثَارِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ابْنَ مَرْيَمَ وَآتَيْنَاهُ الْإِنجِيلَ وَجَعَلْنَا فِي قُلُوبِ الَّذِينَ اتَّبَعُوهُ رَأْفَۃً وَرَحْمَۃً وَرَهْبَانِيَّۃً ابْتَدَعُوهَا مَا كَتَبْنَاهَا عَلَيْهِمْ إِلَّا ابْتِغَاءَ رِضْوَانِ اللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا فَآتَيْنَا الَّذِينَ آمَنُوا مِنْهُمْ أَجْرَهُمْ وَكَثِيرٌ مِّنْهُمْ فَاسِقُونَ‘‘ — پھر ہم نے ان کے پیچھے اپنے رسول بھیجے اور مریم کے بیٹے عیسیٰ کو بھیجا اور اسے انجیل دی اور جنہوں نے اس کی پیروی کی ان کے دلوں میں نرمی اور رحم رکھا — اور راہبانہ جسے انہوں نے از خود ایجاد کیا ہم نے ان پر نہیں لکھا تھا سوائے اللہ کی خوشنودی حاصل کرنے کے — پس انہوں نے اس کی حق روایت نہیں کی — پس جنہوں نے ان میں سے ایمان لایا ہم نے انہیں ان کا اجر دیا — اور ان میں سے اکثر فاسق ہیں — یعنی پھر ہم نے ان کے پیچھے اپنے رسول بھیجے اور مریم کے بیٹے عیسیٰ کو بھیجا اور اسے انجیل دی اور جنہوں نے اس کی پیروی کی ان کے دلوں میں نرمی اور رحم رکھا اور راہبانہ جسے انہوں نے از خود ایجاد کیا ہم نے ان پر نہیں لکھا تھا سوائے اللہ کی خوشنودی حاصل کرنے کے پس انہوں نے اس کی حق روایت نہیں کی پس جنہوں نے ان میں سے ایمان لایا ہم نے انہیں ان کا اجر دیا اور ان میں سے اکثر فاسق ہیں۔
۳۔ عملی سبق: بدعات سے بچو؛ اللہ سے ڈرو۔"""
),
5103: (
"اے ایمان والو اللہ سے ڈرو اور اس کے رسول پر ایمان لاؤ — وہ تمہیں اپنی رحمت سے دو حصے دے گا اور تمہارے لیے نور بنائے گا جس کے ساتھ چلوگے اور تمہیں بخش دے گا — اور اللہ غفور رحیم ہے",
"""۱۔ تقویٰ اور ایمان — یا أیها الذین آمنوا اتقوا الله و آمنوا برسوله یؤتکم کفلین من رحمته و یجعل لکم نورًا تمشون به و یغفر لکم؛ و الله غفور رحیم۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَآمِنُوا بِرَسُولِهِ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِ وَيَغْفِرْ لَكُمْ وَاللَّهُ غَفُورٌ رَّحِيمٌ‘‘ — اے ایمان والو اللہ سے ڈرو اور اس کے رسول پر ایمان لاؤ — وہ تمہیں اپنی رحمت سے دو حصے دے گا اور تمہارے لیے نور بنائے گا جس کے ساتھ چلوگے اور تمہیں بخش دے گا — اور اللہ غفور رحیم ہے — یعنی اے ایمان والو اللہ سے ڈرو اور اس کے رسول پر ایمان لاؤ وہ تمہیں اپنی رحمت سے دو حصے دے گا اور تمہارے لیے نور بنائے گا جس کے ساتھ چلوگے اور تمہیں بخش دے گا اور اللہ غفور رحیم ہے۔
۳۔ عملی سبق: اللہ سے ڈرو اور رسول پر ایمان لاؤ؛ اللہ سے ڈرو۔"""
),
5104: (
"تاکہ اہل کتاب جان لیں کہ وہ اللہ کے فضل میں سے کسی چیز پر قادر نہیں اور فضل اللہ کے ہاتھ میں ہے وہ جسے چاہے دیتا ہے — اور اللہ بہت بڑے فضل والا ہے",
"""۱۔ اللہ کا فضل — لئلا یعلم أهل الکتاب ألا یقدرون علی شيء من فضل الله؛ و أن الفضل بید الله یؤتیه من یشاء؛ و الله ذو الفضل العظیم۔
۲۔ ’’لِّئَلَّا يَعْلَمَ أَهْلُ الْكِتَابِ أَلَّا يَقْدِرُونَ عَلَىٰ شَيْءٍ مِّن فَضْلِ اللَّهِ وَأَنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ‘‘ — تاکہ اہل کتاب جان لیں کہ وہ اللہ کے فضل میں سے کسی چیز پر قادر نہیں اور فضل اللہ کے ہاتھ میں ہے وہ جسے چاہے دیتا ہے — اور اللہ بہت بڑے فضل والا ہے — یعنی تاکہ اہل کتاب جان لیں کہ وہ اللہ کے فضل میں سے کسی چیز پر قادر نہیں اور فضل اللہ کے ہاتھ میں ہے وہ جسے چاہے دیتا ہے اور اللہ بہت بڑے فضل والا ہے۔
۳۔ عملی سبق: اللہ کے فضل کا انتظار کرو؛ اللہ سے ڈرو۔"""
),
}
